  const live = Array.from({ length: 40 }, (_, i) => { const names = ["landing_view", "app_open", "flow_step", "quiz_answer", "cta_click", "reveal_shown", "share_open", "signin_failed"]; const name = names[int(0, names.length - 1)];
    return { created_at: iso(now - i * int(20, 140) * 1000), name, props: name === "flow_step" ? { step: ["name", "score", "sign", "reveal"][int(0, 3)] } : name === "landing_view" ? { page: ["/", "/app", "/tudastar/tetovalas-oregedese"][int(0, 2)] } : name === "signin_failed" ? { provider: "google", why: "You CANNOT use scopes without modifying the main activity." } : {}, src: rnd() > 0.6 ? { us: ["tiktok", "instagram"][int(0, 1)], ux: String(int(1, 9)) } : rnd() > 0.5 ? { from: "www.google.com" } : {}, path: "/app", lang: ["hu", "en", "de"][int(0, 2)], s: rnd().toString(36).slice(2, 8) }; });
  const N = { sessions: S, landing: Math.round(S * 0.77), app: Math.round(S * 0.34), captured: Math.round(S * 0.22), scored: SC, revealed: Math.round(SC * 0.78), paywall: 0, bought: 0, shared: sum("shared"), scored_shared: Math.round(sum("shared") * 0.8), events: S * 6, errors: sum("errors"), signups: sum("signups"), confirmed: Math.round(sum("signups") * 0.9), active_users: 9, unlocks: 5 };
